(function(){"use strict";const root=document.documentElement;root.classList.add("opm-initial-data-pending");let completed=false;const hasData=()=>Array.isArray(window.__ALL_DATA_MASTER)&&window.__ALL_DATA_MASTER.length>0;function ready(){if(completed||!hasData())return;completed=true;root.classList.remove("opm-initial-data-pending","opm-initial-data-delayed");const notice=document.getElementById("uiDataNotice");if(notice){notice.hidden=true;notice.style.display="none"}}document.addEventListener("dataUpdated",ready);document.addEventListener("rocketDataReady",ready);window.addEventListener("load",ready,{once:true});setTimeout(function(){if(completed||hasData()){ready();return}root.classList.remove("opm-initial-data-pending");root.classList.add("opm-initial-data-delayed");const notice=document.getElementById("uiDataNotice");if(notice){notice.hidden=false;notice.style.display="flex";const heading=notice.querySelector("strong"),description=notice.querySelector("p");if(heading)heading.textContent="تأخر تحميل البيانات";if(description)description.textContent="لم تكتمل قراءة البيانات الأساسية بعد. يمكنك إعادة المحاولة من زر تحديث."}},30000)})();